float t2 = dot(StrandDirectionWS, StrandDirectionWS);
float v2 = dot(ViewDirectionWS, ViewDirectionWS);
float l2 = dot(LightDirectionWS, LightDirectionWS);
if (min(t2, min(v2, l2)) < 1e-8) return float2(0, 0);
float3 T = StrandDirectionWS * rsqrt(t2);
float3 V = ViewDirectionWS * rsqrt(v2);
float3 H = LightDirectionWS * rsqrt(l2) + V;
float h2 = dot(H, H);
float along = saturate(abs(dot(T, V)));
if (h2 < 1e-8) return float2(0, along * along);
float th = dot(T, H * rsqrt(h2));
return float2(sqrt(saturate(1 - th * th)) * MaskG, along * along);
